for n in range(N):
    for w in range(W):
        inflow = 0
        outflow = 0
        if w > 0:
            inflow += WestFlow[n][w - 1]
        if n > 0:
            inflow += NorthFlow[n - 1][w]
        if w < W - 1:
            outflow += WestFlow[n][w]
        if n < N - 1:
            outflow += NorthFlow[n][w]
        if (n == 0 and w == 0):
            model.addConstr(outflow - inflow == 1, name=f"FlowSource_{n}_{w}")
        elif (n == N - 1 and w == W - 1):
            model.addConstr(inflow - outflow == 1, name=f"FlowSink_{n}_{w}")
        else:
            model.addConstr(inflow == outflow, name=f"FlowConserv_{n}_{w}")

for n in range(N):
    for w in range(W - 1):
        model.addConstr(WestFlow[n][w] >= 0, name=f"WestFlowNonNeg_{n}_{w}")

for n in range(N - 1):
    for w in range(W):
        model.addConstr(NorthFlow[n][w] >= 0, name=f"NorthFlowNonNeg_{n}_{w}")
